test("claims and sends the personal-plan email only once", async () => {
  const store = createStore()
  const sends: unknown[] = []
  const input = {
    leadId,
    siteUrl: "https://chaarlie.de",
    store,
    send: async (payload: unknown) => {
      sends.push(payload)
